'use strict';
function workHead(title,desc,act="",eyebrow=""){return `<div class="work-head"><div>${eyebrow?`<div class="kicker">${h(eyebrow)}</div>`:""}<h1>${h(title)}</h1><p>${h(desc)}</p></div>${act}</div>`}
function surface(title,content,control=""){return `<section class="surface"><div class="part"><h2>${h(title)}</h2>${control}</div>${content}</section>`}
function panel(title,content){return surface(title,content)}
function inputs(name,label,value="",multi=false,type="text",required=false){const val=h(value);return `<label>${h(label)}${multi?`<textarea name="${name}" rows="3" ${required?"required":""}>${val}</textarea>`:`<input name="${name}" type="${type}" value="${val}" ${required?"required":""}>`}</label>`}
function statusTag(p){return tag(T(names[p.status]||names.captured),p.status==="review"?"accent":p.status==="closed"?"":"good",p.status==="closed"?"":"dot")}
function stat(k,v){return `<div class="stat"><span>${h(k)}</span><strong>${h(v)}</strong></div>`}
function sectionTab(choices,current){return `<div class="tabs">${choices.map(([key,txt])=>`<a class="chip ${key===current?"on":""}" href="#${key}" ${key===current?'aria-current="page"':""}>${h(txt)}</a>`).join("")}</div>`}
function frameGuide(){const prompt=contextPrompts()[0];return `<aside class="inline-guide">${mark(32)}<p><b>assma</b> · ${h(prompt[0])}</p>${btn(L("assma fragen","Ask assma"),"guide")}</aside>`}
function workspace(){let v=S.view,active=["experience","import"].includes(v)?"experience":v==="dashboard"?"dashboard":v==="progress"?"progress":"opportunities";const entries=[["dashboard","Dashboard","grid"],["opportunities",L("Projekte","Projects"),"folder"],["experience",L("Erfahrung","Experience"),"person"],["progress",L("Fortschritt","Progress"),"bars"]];
return `<div class="app ${S.drawer?"drawer":""}"><aside class="rail">${word()}<nav aria-label="${L("Arbeitsbereich","Workspace")}">${entries.map(([k,t,i])=>`<a href="#${k}" class="${active===k?"active":""}" ${v===k?'aria-current="page"':""}>${ic(i)}${t}</a>`).join("")}</nav><div><h3>${L("Deine Projekte","Your projects")}</h3>${S.projects.filter(p=>!p.archived).slice(0,6).map(p=>`<a href="#${p.channel?"application":"fit"}" class="project-link ${S.selected===p.id&&["fit","cv","email","portal","application","snapshot","note"].includes(v)?"active":""}" data-pick="${p.id}">${mark(18)}<span>${h(p.company)}</span></a>`).join("")}${linkBtn(L("Projekt erfassen","Capture project"),"capture","","plus")}</div><div class="rail-foot"><div class="tools">${langButton()}${themeButton()}${toolButton("shortcuts",L("Tastenkürzel","Keyboard shortcuts"),"keyboard")}<a class="icon-btn" href="${GITHUB_URL}" target="_blank" rel="noopener" aria-label="GitHub">${ic("github")}</a></div><span class="meta">${L("Demo-Arbeitsbereich","Demo workspace")} · <b>assma</b></span><a class="meta" href="#home">${L("Zur Landingpage","Back to landing page")}</a></div></aside><div><div class="mobilebar"><button class="icon-btn" data-act="drawer" aria-label="${L("Navigation öffnen","Open navigation")}" aria-expanded="${S.drawer}">${ic("menu")}</button>${word()}${langButton()}${themeButton()}</div><main class="appbody" id="main" tabindex="-1">${contentFor(v)}${frameGuide()}</main></div></div>`}
function contentFor(v){switch(v){case"dashboard":return dashboardView();case"progress":return progressView();case"opportunities":case"archived":return registerView();case"capture":case"manual":return captureView();case"experience":return profileView();case"import":return importView();case"fit":return fitView();case"cv":return cvView();case"email":case"portal":return applyView();case"application":case"snapshot":return recordView();default:return noteView()}}
function dashboardView(){let subs=S.projects.filter(p=>p.channel),open=subs.filter(p=>!p.archived&&p.status!=="closed"),due=open.filter(p=>p.due&&p.due<=demoDay).sort((a,b)=>a.due.localeCompare(b.due));
return workHead("Dashboard",L("Deine Bewerbungen und die nächsten Gespräche im Blick.","Your applications and the conversations that need a follow-up."),linkBtn(L("Neues Projekt","New project"),"capture","primary","plus"),L("Freitag, 20. November · Beispieldaten","Friday, 20 November · sample data"))+
`<div class="stats">${stat(L("Wiedervorlagen fällig","Follow-ups due"),due.length)}${stat(L("Bewerbungen gesendet","Applications submitted"),submissionRecords().length)}${stat(L("Bewerbungen offen","Applications open"),open.length)}</div><h2 class="due-group">${L("Heute nachfassen","Follow up today")}</h2><div class="dual">${due.map(p=>`<article class="card"><div class="card-top">${fruit(p.due<demoDay?40:20)}<div>${tag(p.due<demoDay?L("Überfällig","Overdue"):L("Heute fällig","Due today"),"warn")}<h3>${h(p.company)}</h3></div></div><p class="meta">${h(p.title)} · ${h(p.contact||"")}</p><div class="next"><span class="tiny">${L("Nächster Schritt","Next step")}</span><div class="part" style="margin:0"><strong>${h(p.contact||p.company)} ${L("kontaktieren","· follow up")}</strong>${btn(L("Nachfassen","Follow up"),"pick-note","","mail",p.id)}</div></div></article>`).join("")||`<div class="surface">${L("Alles erledigt.","All caught up.")}</div>`}</div><div style="margin-top:1rem">${surface(L("Letzte Bewerbungen","Recent applications"),subs.slice().sort((a,b)=>b.when.localeCompare(a.when)).slice(0,3).map(p=>`<div class="row"><div><button class="tabletitle" data-act="pick-record" data-id="${p.id}">${h(p.title)}</button><small>${h(p.company)}</small></div>${statusTag(p)}<span class="meta">${formatDate(p.when,true)}</span></div>`).join(""),linkBtn(L("Alle Projekte","All projects"),"opportunities"))}</div>`}
function registerRows(){let items=S.projects.filter(p=>Boolean(p.archived)===(S.view==="archived")&&(S.activeFilter==="all"||p.status===S.activeFilter)&&((p.title+" "+p.company+" "+p.tech).toLowerCase().includes(S.search.toLowerCase())));return items.map(p=>`<tr><td><button class="tabletitle" data-act="pick-record" data-id="${p.id}">${h(p.title)}</button><small>${h(p.company)}</small></td><td>${statusTag(p)}</td><td>${h(p.tech)}</td><td>${formatDate(p.when,true)}</td><td>${p.score?`${p.score}/10`:"–"}</td><td><button class="icon-btn" data-act="menu" data-id="${p.id}" aria-label="${h(p.company+" · "+L("Aktionen","Actions"))}">${ic("dots")}</button></td></tr>`).join("")||`<tr><td class="empty" colspan="6">${L("Keine passenden Projekte.","No matching projects.")}</td></tr>`}
function registerView(){const n=S.projects.filter(p=>!p.archived).length;return workHead(L("Projekte","Projects"),L("Bei welchem Unternehmen hast du dich beworben und mit welchem Profil?","Which company did you apply to, and which profile did you send?"),linkBtn(L("Neues Projekt","New project"),"capture","primary","plus"))+sectionTab([["opportunities",L("Aktiv","Active")+" · "+n],["archived",L("Archiv","Archive")+" · "+(S.projects.length-n)]],S.view)+`<div class="surface filters"><input class="in" id="search" value="${h(S.search)}" aria-label="${L("Projekte suchen","Search projects")}" placeholder="${L("Titel oder Unternehmen","Title or company")}">${["all","captured","sent","review","interview","closed"].map(k=>`<button class="chip" data-act="filter" data-id="${k}" aria-pressed="${S.activeFilter===k}">${k==="all"?L("Alle","All"):T(names[k])}</button>`).join("")}</div><div class="surface tablewrap"><table class="register"><thead><tr>${[L("Projekt / Unternehmen","Project / company"),"Status",L("Tech-Stack","Tech stack"),L("Datum und Uhrzeit","Date and time"),L("Passung","Fit"),""].map(t=>`<th scope="col">${h(t)}</th>`).join("")}</tr></thead><tbody id="regrows">${registerRows()}</tbody></table></div>`}
function captureView(){S.fields??=captureDefaults();let p=S.fields,m=S.view==="manual";return workHead(L("Projekt erfassen","Capture opportunity"),L("assma schlägt Felder aus der Ausschreibung vor. Du prüfst sie neben der Quelle.","assma suggests fields from the brief. Review them alongside the source."))+
sectionTab([["capture",L("Projektlink oder Text","Listing link or text")],["manual",L("Manuell erfassen","Enter manually")]],S.view)+`<form id="capture-form" class="form"><div class="split">${panel(m?L("Manuelle Erfassung","Manual entry"):L("Ausschreibung","Source listing"),`<div class="form">${inputs("url",L("Projektlink","Project URL"),p.url)}${inputs("text",L("Text der Ausschreibung","Listing text"),p.text,true)}${m?`<p class="meta">${L("Trage die Projektdaten direkt ein. Link und Ausschreibungstext kannst du als Quelle ergänzen.","Enter the project details yourself. Keep the link and original text as a reference if available.")}</p>`:`<div class="acts">${btn(L("Beispiel laden","Load example"),"example")}${btn(L("Felder vorschlagen","Suggest fields"),"suggest","primary","spark")}</div>`}${S.captureNeedsPaste?`<div class="notice-line">${L("Füge den sichtbaren Text ein oder erfasse die Projektfelder direkt.","Paste the visible brief or enter the fields directly.")}</div>`:""}</div>`)}
${surface(L("Projektdaten","Project details"),`<div class="form">${inputs("title",L("Projekttitel","Project title"),p.title,false,"text",true)}${inputs("company",L("Endkunde","End client"),p.company,false,"text",true)}<div class="dual">${inputs("agency",L("Vermittlung","Agency"),p.agency)}${inputs("contact",L("Kontakt","Contact"),p.contact)}</div>${inputs("tech",L("Tech-Stack","Tech stack"),p.tech)}${inputs("required",L("Erforderliche Erfahrung","Required experience"),p.required,true)}${inputs("preferred",L("Wünschenswert","Preferred experience"),p.preferred)}${inputs("terms",L("Ort, Remote und Laufzeit","Location, remote and duration"),p.terms)}</div>`,tag(!m&&S.captureSuggested?L("Vorschläge prüfen","Review suggestions"):L("Deine Eingabe","Your input"),!m&&S.captureSuggested?"accent":""))}</div><footer><button class="btn primary" type="submit">${L("Speichern und Passung prüfen","Save and assess fit")}</button>${linkBtn(L("Zur Übersicht","Back to projects"),"opportunities")}</footer></form>`}
function profileView(){let p=S.profile;return workHead(L("Deine Erfahrung","Your experience"),L("Dein Profil und die Projekte, auf die sich assma bei Bewerbungen stützt.","Your profile and the projects assma can cite in an application."),linkBtn(L("CV importieren","Import CV"),"import","primary","upload"))+`<div class="split">${panel(L("Projektreferenzen","Project references"),S.refs.map(r=>`<article class="evidence"><h3><span class="codelabel">${h(r.id)}</span>${h(r.org)}</h3><p>${h(r.role)} · ${h(r.years)}</p><p>${h(T(r.body))}</p><span class="meta">${h(r.skills)}</span> ${btn(L("Bearbeiten","Edit"),"ref-edit","","edit",r.id)}</article>`).join("")+btn(L("Referenz hinzufügen","Add reference"),"ref-add","","plus"))}${surface(L("Persönliche Angaben","General profile"),`<div class="stack"><strong>${h(p.name)}</strong><p>${h(p.role)}<br>${h(p.location)}<br>${h(p.email)}</p><p class="meta">${h(T(p.summary))}</p>${btn(L("Angaben bearbeiten","Edit profile"),"profile-edit","","edit")}</div>`)}</div>`}
function importView(){return workHead(L("CV-Import prüfen","Review CV import"),L("Vergleiche die vorgeschlagenen Angaben mit dem Beispiel-CV und bestätige deine Auswahl.","Compare the suggested entries with the example CV and confirm your selection."))+`<div class="split">${panel(L("Quelldokument","Source document"),`<div class="previewpaper"><h2>Mara Linden</h2><p>Android Engineer · Düsseldorf</p>${sampleRefs.map(r=>`<h3>${h(r.org)}</h3><p>${r.years}<br>${h(T(r.body))}</p>`).join("")}</div>`)}${panel(L("Vorschläge von assma","Suggestions from assma"),`<form id="import-form" class="form">${sampleRefs.map((r,i)=>`<label class="checkrow"><input type="checkbox" value="${r.id}" name="refs" ${S.imported[i]?"checked":""}><span><b>${h(r.org)}</b><br>${h(r.role)} · ${r.years}</span></label>`).join("")}<button class="btn primary" type="submit">${L("Auswahl übernehmen","Confirm selection")}</button></form>`)}</div>`}
const normal=s=>String(s||"").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"");
function assess(p){const seeded=p.id==="aster"||(p.title===initialTitle&&p.company==="Aster Care");if(seeded){
const arr=[
 [L("Kotlin und Jetpack Compose","Kotlin and Jetpack Compose"),true,"E01","full",L("Patienten-Check-in in Kotlin und Compose.","Patient check-in built with Kotlin and Compose.")],
 [L("Offline-first-Android","Offline-first Android"),true,"E01","full",L("Lokale Warteschlange für Eingaben ohne Netz.","Local queue for offline submissions.")],
 [L("Android-Barrierefreiheit","Accessible Android interfaces"),true,"E02","full",L("Ticketkauf mit TalkBack getestet.","Ticket purchasing tested with TalkBack.")],
 [L("Release-Verantwortung","Release ownership"),false,"E03","partial",L("CI-Prüfungen belegt. Gesamtverantwortung offen.","CI checks are evidenced. Overall ownership is open.")],
 ["FHIR R4",false,"","open",L("Kein bestätigter Projektbeleg.","No confirmed project evidence.")]];
const terms=[[/kotlin/,/compose/],[/queue|warteschlange|offline/],[/talkback/],[/\bci\b/],[]];
return arr.map((a,i)=>{if(!a[2])return a;const ref=S.refs.find(r=>r.id===a[2]),body=normal(T(ref?.body));if(!ref||!terms[i].every(rule=>rule.test(body)))return [a[0],a[1],"","open",L("Aktuell kein bestätigter Beleg.","No confirmed evidence in the current profile.")];const original=sampleRefs.find(r=>r.id===a[2]);return T(original?.body)===T(ref.body)?a:[a[0],a[1],a[2],a[3],T(ref.body)]})}
const parts=(s,required)=>String(s||"").split(/[,;\n]+/).map(x=>x.trim()).filter(Boolean).map(req=>{let key=normal(req);let r=S.refs.find(ref=>key.length>2&&normal(ref.skills+" "+T(ref.body)).includes(key));return [req,required,r?.id||"",r?"full":"open",r?T(r.body):L("Noch kein direkter Beleg im Profil.","No direct evidence in the profile yet.")]});return [...parts(p.required||p.tech?.replace(/·/g,","),true),...parts(p.preferred,false)]}
function getScore(rows){let total=0,earned=0;for(const r of rows){const weight=r[1]?2:1;total+=weight;earned+=weight*(r[3]==="full"?1:r[3]==="partial"?.5:0)}return total?Math.max(1,Math.round(10*earned/total)):null}
function fitView(){const p=project();if(!p)return registerView();const rows=assess(p),score=getScore(rows);return workHead(p.title,p.company+" · "+(p.agency||p.tech||""),linkBtn(L("Passenden CV entwerfen","Draft tailored CV"),"cv","primary","spark"))+
`<div class="fit-top">${surface(L("Erfahrungspassung","Experience fit"),`<div class="score">${score??"–"}<small> / 10</small></div><div class="meter">${Array.from({length:10},(_,i)=>`<i class="${i<(score||0)?"on":""}"></i>`).join("")}</div><p class="meta">${L("Pflichtanforderungen zählen doppelt.","Required experience carries double weight.")}</p>`)}${surface(L("Was spricht für dich?","Where is your strongest evidence?"),`<p class="goodtext"><b>${L("Stärken","Strengths")}</b></p><p class="meta">${h(rows.filter(r=>r[3]==="full").map(r=>r[0]).join(", ")||"–")}</p><p class="warntext"><b>${L("Offene Punkte","Gaps to clarify")}</b></p><p class="meta">${h(rows.filter(r=>r[3]!=="full").map(r=>r[0]).join(", ")||"–")}</p>`)}</div>${surface(L("Anforderungen und Belege","Requirements and evidence"),rows.map(r=>`<div class="finding"><div><strong>${h(r[0])}</strong><p>${r[1]?L("Erforderlich","Required"):L("Wünschenswert","Preferred")}</p></div><span>${tag(r[3]==="full"?L("Belegt","Evidenced"):r[3]==="partial"?L("Teilweise","Partial"):L("Offen","Open"),r[3]==="full"?"good":r[3]==="partial"?"warn":"","")}</span><p>${h(r[4])}${r[2]?` <a class="codelabel" data-act="show-ref" data-id="${r[2]}" href="#experience">${r[2]}</a>`:""}</p></div>`).join("")+`<p class="meta">${L("Rahmenbedingungen","Working terms")} · ${h(p.terms||(p.id==="aster"?L("Düsseldorf · 80 % remote · 6 Monate","Düsseldorf · 80% remote · six months"):"–"))}</p>`)}`}
function paper(s){return `<div class="previewpaper"><h2>${h(s.name)}</h2><p>${h(s.role)} · ${h(s.location)}<br>${h(s.email)}</p><h3>${L("Profil","Profile")}</h3><p>${h(s.summary)}</p>${s.refs.map(r=>`<h3>${h(r.org)}</h3><p class="meta">${h(r.role)} · ${h(r.years)}</p><p>${h(r.body)}</p>`).join("")}</div>`}
function cvView(){let p=project();if(!p)return registerView();const s=snapshotData(p,"","");let sorted=[...S.included,...S.refs.map(r=>r.id).filter(r=>!S.included.includes(r))].map(id=>S.refs.find(r=>r.id===id)).filter(Boolean);return workHead(L("Dein passender CV","Your tailored CV"),p.title+" · "+p.company,linkBtn(L("Für Bewerbung verwenden","Use for application"),"email","primary","send"))+`<div class="split">${surface(L("CV-Inhalt","CV content"),`<div class="form">${inputs("cvsummary",L("Kurzprofil","Profile summary"),s.summary,true)}<h3>${L("Ausgewählte Referenzen","Selected references")}</h3>${sorted.map(r=>`<div class="cvrow"><label class="checkrow"><input type="checkbox" name="cvref" value="${r.id}" ${S.included.includes(r.id)?"checked":""}><span>${h(r.org)} <small>${r.id}</small></span></label>${S.included.indexOf(r.id)>0?btn(L("Nach oben","Move up"),"ref-up","","",r.id):""}</div>`).join("")}<div class="acts">${btn("Markdown","download-md","","download")}${btn("PDF","download-pdf","","download")}</div></div>`)}${surface(L("Vorschau","Preview"),`<div id="cv-paper">${paper(s)}</div>`)}</div>`}
function applyView(){const p=project();if(!p)return registerView();let portal=S.view==="portal",s=snapshotData(p,"","");return workHead(L("Auf das Projekt bewerben","Apply to the project"),p.title+" · "+p.company)+sectionTab([["email",L("E-Mail versenden","Send email")],["portal",L("Portalbewerbung vermerken","Record portal application")]],S.view)+`<div class="split">${surface(portal?L("Vorgang im Portal","Portal submission"):L("Nachricht","Message"),`<form id="apply-form" class="form">${portal?`${inputs("when",L("Eingereicht am · Ortszeit","Submitted at · local time"),S.portalTime,false,"datetime-local",true)}${inputs("url",L("Projektlink","Project URL"),p.url||"")}<label>${L("Hochgeladener CV","Uploaded CV")}<select name="portalFile"><option value="sample" ${S.portalFile==="sample"?"selected":""}>${h(cvName(p))}</option><option value="none" ${S.portalFile==="none"?"selected":""}>${L("Kein CV hochgeladen","No CV uploaded")}</option><option value="own" ${S.portalFile==="own"?"selected":""}>${L("Eigene PDF auswählen","Choose my PDF")}</option></select></label><label id="port-file-wrap" ${S.portalFile!=="own"?"hidden":""}>${L("Tatsächlich hochgeladene PDF","Actual PDF uploaded")}<input type="file" name="actualfile" accept="application/pdf" ${S.portalFile==="own"?"required":""}></label>`:`${inputs("to",L("Empfänger","Recipient"),p.email||"kontakt@example.org",false,"email",true)}${inputs("subject",L("Betreff","Subject"),p.title+" · "+S.profile.name,false,"text",true)}${inputs("message",L("Nachricht","Message"),L("Hallo, anbei mein Profil für das ausgeschriebene Projekt. Gerne erläutere ich meine Referenzen in einem Gespräch. Viele Grüße, Mara","Hello, I have attached my profile for the project. I would be happy to discuss my references. Best, Mara"),true)}<p class="notice-line">${L("Beispielversand im Browser. Die Nachricht bleibt in dieser Vorschau.","Demo delivery in the browser. The message stays in this preview.")}</p>`}${inputs("due",L("Nächste Wiedervorlage","Next follow-up"),p.due||demoDay,false,"date")}<button class="btn primary" type="submit">${portal?L("Portalvorgang speichern","Save portal record"):L("Beispielversand bestätigen","Confirm example delivery")}</button></form>`)}${surface(L("Fassung für diese Bewerbung","Version for this application"),`<div class="stack">${tag(L("Privater Snapshot","Private snapshot"),"accent","lock")}<strong>${h(cvName(p))}</strong><p class="meta">${h(s.refs.map(x=>x.org).join(" · "))}</p>${linkBtn(L("CV überprüfen","Review CV"),"cv")}<p class="meta">${L("assma hält Ausschreibung, Erfahrung und freigegebenen Wortlaut zum Versandzeitpunkt fest.","assma preserves the listing, experience and approved wording at the time of submission.")}</p></div>`)}</div>`}
function versionsFor(id){return [S.snapshots[id],...(S.archiveSnapshots?.[id]||[]).slice().reverse()].filter(Boolean)}
function selectedSnapshot(id){const all=versionsFor(id);return all[S.snapIndex||0]||all[0]}
function snapshotPicker(id){const versions=versionsFor(id);if(versions.length<2)return "";return `<div class="form version-picker"><label>${L("Gespeicherte Bewerbungen","Saved submissions")}<select name="snapshotVersion">${versions.map((s,i)=>`<option value="${i}" ${i===(S.snapIndex||0)?"selected":""}>${formatDate(s.when,true)} · ${s.channel==="portal"?"Portal":"E-Mail"} · ${i===0?L("Neueste","Latest"):"#"+(versions.length-i)}</option>`).join("")}</select></label></div>`}
function recordView(){const p=project();if(!p)return registerView();let s=selectedSnapshot(p.id),snap=S.view==="snapshot";let entries=S.notes[p.id]||[];return workHead(p.title,p.company+" · "+(p.contact||p.agency||""),linkBtn(L("Notiz ergänzen","Add note"),"note","primary","note"))+
`<div class="stats">${stat("Status",T(names[p.status]))}${stat(L("Kanal","Channel"),p.channel==="portal"?"Portal":p.channel==="email"?"E-Mail":"–")}${stat(L("Wiedervorlage","Follow-up"),formatDate(p.due))}</div>`+sectionTab([["application",L("Verlauf","Activity")],["snapshot",L("Versendete Fassung","Submission snapshot")]],S.view)+
(snap?s?snapshotPicker(p.id)+`<div class="split">${panel(L("Stand bei der Bewerbung","Data at submission"),`<div class="stack"><b>${formatDate(s.when,true)}</b><p>${h(s.project.title)} · ${h(s.project.company)}</p><p class="meta">${h(s.source)}</p><p>${L("Erfahrungspassung","Experience fit")} · ${s.score?s.score+"/10":"–"}</p>${s.assessment?.length?`<details><summary>${L("Belege zum Zeitpunkt der Bewerbung","Evidence at submission")}</summary>${s.assessment.map(r=>`<p class="meta"><strong>${h(r[0])}</strong> · ${h(r[2]||"–")}<br>${h(r[4])}</p>`).join("")}</details>`:""}${paper(s)}</div>`)}${panel(L("Ursprüngliche Datei","Original file"),`<div class="stack"><b>${h(s.fileName||L("Kein CV hinterlegt","No CV attached"))}</b>${s.fileBytes?btn(L("Original-PDF laden","Download original PDF"),"original","primary","download"):""}<h3>${L("Aus Snapshot erzeugen","Regenerate from snapshot")}</h3><div class="acts">${btn("Markdown","snap-md","","download")}${btn("PDF","snap-pdf","","download")}</div></div>`)}</div>`:panel(L("Versendete Fassung","Submission snapshot"),`<p class="meta">${L("Hier erscheint der Snapshot nach der ersten Bewerbung.","The snapshot appears after the first submission.")}</p>${linkBtn(L("Zur Bewerbung","Apply"),"email")}`):
`<div class="split">${panel(L("Bewerbungsverlauf","Application history"),[...entries].reverse().map(n=>`<div class="row"><div><strong>${L("Notiz / Rückmeldung","Note / reply")}</strong><small>${formatDate(n.date,true)}</small><p>${h(T(n.body))}</p></div></div>`).join("")+`<div class="row"><div><strong>${p.channel?(p.channel==="portal"?L("Portalbewerbung vermerkt","Portal submission recorded"):L("Bewerbung per E-Mail","Application by email")):L("Projekt erfasst","Project captured")}</strong><small>${formatDate(p.when,true)}</small>${s?.recipient?`<p>${h(s.recipient)}</p>`:""}</div></div>`)}${panel(L("Nächster Kontakt","Next contact"),`<div class="stack"><b>${h(p.contact||p.company)}</b><span class="meta">${h(p.email||"")}</span><div class="acts">${btn(L("Mit assma nachfassen","Follow up with assma"),"guide","primary","spark")}${linkBtn(L("Passung ansehen","Open fit"),"fit")}${btn(L("Projektaktionen","Project actions"),"menu","","dots",p.id)}</div></div>`)}</div>`)}
function noteView(){const p=project();if(!p)return registerView();return workHead(L("Kontakt festhalten","Record a follow-up"),p.title+" · "+p.company)+panel(L("Rückmeldung oder Notiz","Reply or note"),`<form id="note-form" class="form">${inputs("body",L("Was wurde besprochen?","What did you discuss?"),"",true)}<div class="dual"><label>${L("Bewerbungsstatus","Application status")}<select name="status">${Object.keys(names).filter(x=>p.channel?x!=="captured":x==="captured").map(k=>`<option value="${k}" ${p.status===k?"selected":""}>${T(names[k])}</option>`).join("")}</select></label>${inputs("due",L("Wiedervorlage","Follow-up"),p.due||demoDay,false,"date")}</div><footer><button class="btn primary" type="submit">${L("Vermerken","Save update")}</button>${linkBtn(L("Zurück","Back"),"application")}</footer></form>`)}

